#!/usr/bin/env node
/**
 * Nektar Deterministic Chrome-CDP -> FFmpeg Video Renderer (Zero npm dependencies, Node 24+)
 * Usage: node videos/shared/render.mjs <sceneDir> [outMp4] [--preview] [--png] [--concurrency=2]
 *
 * Expects in <sceneDir>:
 *   - scene.html      exposing window.renderFrame(t, frame, totalFrames, timings)
 *   - timings.json    generated by videos/shared/tts.mjs
 *   - audio-mix.wav   generated by videos/shared/tts.mjs (required for full MP4 mode)
 */

import fs from 'node:fs';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import { spawn, execFileSync } from 'node:child_process';
import { once } from 'node:events';

function die(msg) {
  console.error(`[render.mjs] ERROR: ${msg}`);
  process.exit(1);
}

const args = process.argv.slice(2);
const flags = new Set(args.filter((a) => a.startsWith('--') && !a.includes('=')));
const kvFlags = Object.fromEntries(
  args.filter((a) => a.startsWith('--') && a.includes('=')).map((a) => {
    const idx = a.indexOf('=');
    return [a.slice(2, idx), a.slice(idx + 1)];
  })
);
const positional = args.filter((a) => !a.startsWith('--'));

if (positional.length < 1) {
  die('Usage: node videos/shared/render.mjs <sceneDir> [outMp4] [--preview] [--png] [--concurrency=2] [--no-audio]');
}

const previewOnly = flags.has('--preview');
const usePng = flags.has('--png');
const noAudio = flags.has('--no-audio');
const CONCURRENCY = Math.max(1, Math.min(4, Number(kvFlags.concurrency || 1)));

const sceneDir = path.resolve(positional[0]);
const outMp4 = positional[1]
  ? path.resolve(positional[1])
  : path.resolve(sceneDir, `${path.basename(sceneDir)}.mp4`);

const sceneHtml = path.join(sceneDir, 'scene.html');
const timingsPath = path.join(sceneDir, 'timings.json');
const audioPath = path.join(sceneDir, 'audio-mix.wav');

if (!fs.existsSync(sceneHtml)) die(`scene.html not found: ${sceneHtml}`);
if (!fs.existsSync(timingsPath)) die(`timings.json not found: ${timingsPath} (run tts.mjs first)`);
if (!previewOnly && !noAudio && !fs.existsSync(audioPath)) {
  die(`audio-mix.wav not found: ${audioPath} (run tts.mjs first, or pass --no-audio)`);
}

const timings = JSON.parse(fs.readFileSync(timingsPath, 'utf8'));
const WIDTH = Number(kvFlags.width || 1920);
const HEIGHT = Number(kvFlags.height || 1080);
const FPS = Number(timings.fps || 30);
const TOTAL_FRAMES = Number(timings.totalFrames || Math.ceil(Number(timings.totalDuration) * FPS));

// ---------- Locate Cached Chrome / Edge Binary ----------

function findBrowser() {
  const candidates = [
    process.env.NEKTAR_CHROME_BIN,
    'C:\\Users\\nedzo\\.cache\\puppeteer\\chrome-headless-shell\\win64-155.0.8059.39\\chrome-headless-shell-win64\\chrome-headless-shell.exe',
    'C:\\Users\\nedzo\\puppeteer-browsers\\chrome\\win64-157.0.8103.78\\chrome-win64\\chrome.exe',
    'C:\\Users\\nedzo\\.cache\\puppeteer\\chrome\\win64-155.0.8059.39\\chrome-win64\\chrome.exe',
    'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
    'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe'
  ].filter(Boolean);

  for (const p of candidates) {
    if (fs.existsSync(p)) return p;
  }
  die(`No Chrome/Edge binary found. Checked:\n${candidates.join('\n')}`);
}

// ---------- Ephemeral Local Static Server (127.0.0.1:0 — zero file:// CORS quirks) ----------

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.wav': 'audio/wav',
  '.mp3': 'audio/mpeg'
};

async function startStaticServer(rootDir) {
  const server = http.createServer((req, res) => {
    try {
      const urlPath = decodeURIComponent((req.url || '/').split('?')[0]);
      const safePath = path.resolve(rootDir, '.' + urlPath);
      if (!safePath.startsWith(rootDir) || !fs.existsSync(safePath) || fs.statSync(safePath).isDirectory()) {
        res.writeHead(404);
        res.end('Not found');
        return;
      }
      const ext = path.extname(safePath).toLowerCase();
      res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream', 'Cache-Control': 'no-store' });
      fs.createReadStream(safePath).pipe(res);
    } catch (e) {
      res.writeHead(500);
      res.end(String(e));
    }
  });
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });
  return { server, port: server.address().port };
}

// ---------- Minimal Native WebSocket CDP Client ----------

class CDPClient {
  constructor(wsUrl) {
    this.wsUrl = wsUrl;
    this.nextId = 1;
    this.pending = new Map();
    this.listeners = new Map();
  }

  async connect() {
    this.ws = new WebSocket(this.wsUrl);
    await new Promise((resolve, reject) => {
      this.ws.addEventListener('open', resolve, { once: true });
      this.ws.addEventListener('error', (e) => reject(new Error(`CDP WS error: ${e.message || 'failed'}`)), { once: true });
    });
    this.ws.addEventListener('message', (ev) => {
      const msg = JSON.parse(typeof ev.data === 'string' ? ev.data : ev.data.toString('utf8'));
      if (msg.id !== undefined) {
        const entry = this.pending.get(msg.id);
        if (entry) {
          this.pending.delete(msg.id);
          if (msg.error) entry.reject(new Error(`CDP ${entry.method} failed: ${msg.error.message}`));
          else entry.resolve(msg.result);
        }
      } else if (msg.method) {
        const list = this.listeners.get(msg.method);
        if (list) {
          for (const fn of [...list]) fn(msg.params);
        }
      }
    });
  }

  send(method, params = {}) {
    const id = this.nextId++;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject, method });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }

  waitForEvent(method, timeoutMs = 15000) {
    let timer;
    let off = () => {};
    const promise = new Promise((resolve, reject) => {
      timer = setTimeout(() => {
        off();
        reject(new Error(`Timed out waiting for CDP event: ${method}`));
      }, timeoutMs);
      const handler = (params) => {
        clearTimeout(timer);
        off();
        resolve(params);
      };
      off = () => {
        clearTimeout(timer);
        const list = this.listeners.get(method);
        if (list) this.listeners.set(method, list.filter((f) => f !== handler));
      };
      if (!this.listeners.has(method)) this.listeners.set(method, []);
      this.listeners.get(method).push(handler);
    });
    return { promise, cancel: off };
  }

  close() {
    try { this.ws?.close(); } catch {}
  }
}

async function launchChrome(browserBin, userDataDir) {
  const isHeadlessShell = browserBin.toLowerCase().includes('chrome-headless-shell');
  const chromeArgs = [
    isHeadlessShell ? '--headless' : '--headless=new',
    '--remote-debugging-port=0',
    `--user-data-dir=${userDataDir}`,
    `--window-size=${WIDTH},${HEIGHT}`,
    '--force-device-scale-factor=1',
    '--hide-scrollbars',
    '--mute-audio',
    '--no-first-run',
    '--no-default-browser-check',
    '--disable-background-networking',
    '--disable-extensions',
    '--disable-sync',
    '--disable-translate',
    '--disable-gpu-sandbox',
    '--allow-file-access-from-files',
    'about:blank'
  ];

  const proc = spawn(browserBin, chromeArgs, { stdio: ['ignore', 'pipe', 'pipe'] });
  let stderrBuf = '';

  const browserWsUrl = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`Chrome failed to expose DevTools port. Stderr:\n${stderrBuf}`)), 20000);
    const onData = (chunk) => {
      stderrBuf += chunk.toString('utf8');
      const m = stderrBuf.match(/DevTools listening on (ws:\/\/127\.0\.0\.1:(\d+)\/\S+)/);
      if (m) {
        clearTimeout(timer);
        proc.stderr.off('data', onData);
        resolve(m[1]);
      }
    };
    proc.stderr.on('data', onData);
    proc.once('exit', (code) => {
      clearTimeout(timer);
      reject(new Error(`Chrome exited prematurely (${code}). Stderr:\n${stderrBuf}`));
    });
  });

  const port = Number(browserWsUrl.match(/:(\d+)\//)[1]);
  return { proc, port, browserWsUrl };
}

async function initPageWorker(wsUrl, pageUrl) {
  const cdp = new CDPClient(wsUrl);
  await cdp.connect();
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await cdp.send('Emulation.setDeviceMetricsOverride', {
    width: WIDTH,
    height: HEIGHT,
    deviceScaleFactor: 1,
    mobile: false
  });

  const ev = cdp.waitForEvent('Page.loadEventFired', 20000);
  const navRes = await cdp.send('Page.navigate', { url: pageUrl });
  if (navRes?.errorText) {
    ev.cancel();
    die(`Navigation failed (${pageUrl}): ${navRes.errorText}`);
  }
  await Promise.race([
    ev.promise,
    (async () => {
      for (let i = 0; i < 150; i++) {
        await new Promise((r) => setTimeout(r, 80));
        const st = await cdp.send('Runtime.evaluate', {
          expression: `document.readyState === 'complete' && location.href.startsWith('http://127.0.0.1:')`,
          returnByValue: true
        });
        if (st.result?.value === true) return;
      }
      throw new Error('Timed out waiting for page readyState=complete');
    })()
  ]);
  ev.cancel();

  const initCheck = await cdp.send('Runtime.evaluate', {
    expression: `(async () => {
      window.__TIMINGS__ = ${JSON.stringify(timings)};
      if (document.fonts && document.fonts.ready) await document.fonts.ready;
      if (typeof window.initScene === 'function') await window.initScene(window.__TIMINGS__);
      return typeof window.renderFrame;
    })()`,
    awaitPromise: true,
    returnByValue: true
  });
  if (initCheck.exceptionDetails) {
    die(`Scene init exception: ${JSON.stringify(initCheck.exceptionDetails)}`);
  }
  if (initCheck.result?.value !== 'function') {
    die(`scene.html must define global window.renderFrame(t, frame, totalFrames, timings). Got: ${initCheck.result?.value}`);
  }

  return cdp;
}

// ---------- Main Execution ----------

const browserBin = findBrowser();
const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'nektar-render-'));
const t0 = Date.now();

const sharedDir = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const serveRoot = path.resolve(sharedDir, '..');
const relSceneUrl = '/' + path.relative(serveRoot, sceneHtml).split(path.sep).map(encodeURIComponent).join('/');

let httpServer = null;
let chromeProc = null;
let browserCdp = null;
const pageWorkers = [];

try {
  const srv = await startStaticServer(serveRoot);
  httpServer = srv.server;
  const pageUrl = `http://127.0.0.1:${srv.port}${relSceneUrl}`;

  const numTabs = previewOnly ? 1 : CONCURRENCY;
  console.log(`[render.mjs] Launching ${path.basename(browserBin)} (${numTabs} tab${numTabs > 1 ? 's' : ''}, ${usePng || previewOnly ? 'png' : 'jpeg q92'})`);
  const launched = await launchChrome(browserBin, userDataDir);
  chromeProc = launched.proc;

  // Create extra page targets via browser-level CDP when numTabs > 1
  browserCdp = new CDPClient(launched.browserWsUrl);
  await browserCdp.connect();
  for (let i = 1; i < numTabs; i++) {
    await browserCdp.send('Target.createTarget', { url: 'about:blank' });
  }

  let pageUrls = [];
  for (let tries = 0; tries < 25; tries++) {
    const res = await fetch(`http://127.0.0.1:${launched.port}/json/list`);
    const targets = await res.json();
    pageUrls = targets.filter((t) => t.type === 'page' && t.webSocketDebuggerUrl).map((t) => t.webSocketDebuggerUrl);
    if (pageUrls.length >= numTabs) break;
    await new Promise((r) => setTimeout(r, 60));
  }
  if (pageUrls.length < 1) die('Could not find any Chrome page DevTools targets.');

  const initialized = await Promise.all(pageUrls.slice(0, numTabs).map((u) => initPageWorker(u, pageUrl)));
  pageWorkers.push(...initialized);

  const captureParams = (usePng || previewOnly)
    ? { format: 'png', fromSurface: true }
    : { format: 'jpeg', quality: 92, fromSurface: true, optimizeForSpeed: true };

  async function renderFrameOn(worker, frameIdx) {
    const t = frameIdx / FPS;
    const maxAttempts = 5;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        const evalRes = await worker.send('Runtime.evaluate', {
          expression: `window.renderFrame(${t}, ${frameIdx}, ${TOTAL_FRAMES}, window.__TIMINGS__)`,
          returnByValue: false
        });
        if (evalRes.exceptionDetails) {
          throw new Error(`renderFrame(${t.toFixed(3)}) threw: ${evalRes.exceptionDetails.text || JSON.stringify(evalRes.exceptionDetails)}`);
        }
        const shot = await worker.send('Page.captureScreenshot', captureParams);
        if (!shot || !shot.data) throw new Error('Empty screenshot payload');
        return Buffer.from(shot.data, 'base64');
      } catch (err) {
        const msg = String(err?.message || err);
        const isTransient = msg.includes('Unable to capture screenshot') || msg.includes('Empty screenshot') || msg.includes('Protocol error');
        if (!isTransient || attempt === maxAttempts) throw err;
        const backoffMs = 150 * attempt;
        console.warn(`[render.mjs] WARN frame ${frameIdx} attempt ${attempt}/${maxAttempts} failed (${msg}); retrying in ${backoffMs}ms...`);
        await new Promise((r) => setTimeout(r, backoffMs));
      }
    }
  }

  if (previewOnly) {
    const previewDir = path.join(sceneDir, 'preview');
    fs.mkdirSync(previewDir, { recursive: true });
    for (let i = 0; i < timings.scenes.length; i++) {
      const sc = timings.scenes[i];
      const midT = sc.start + sc.duration * 0.52;
      const frameIdx = Math.min(TOTAL_FRAMES - 1, Math.max(0, Math.round(midT * FPS)));
      const png = await renderFrameOn(pageWorkers[0], frameIdx);
      const outPng = path.join(previewDir, `${String(i + 1).padStart(2, '0')}-${sc.id}.png`);
      fs.writeFileSync(outPng, png);
      console.log(`[render.mjs] Preview saved: ${outPng} (t=${midT.toFixed(2)}s)`);
    }
    console.log(`[render.mjs] Preview complete in ${((Date.now() - t0) / 1000).toFixed(1)}s`);
  } else {
    fs.mkdirSync(path.dirname(outMp4), { recursive: true });
    const ffArgs = [
      '-y', '-v', 'error',
      '-f', 'image2pipe',
      '-vcodec', usePng ? 'png' : 'mjpeg',
      '-r', String(FPS),
      '-i', 'pipe:0'
    ];
    if (!noAudio) {
      ffArgs.push('-i', audioPath);
    }
    ffArgs.push(
      '-map', '0:v:0',
      ...(noAudio ? ['-an'] : ['-map', '1:a:0']),
      '-vf', usePng
        ? 'scale=out_color_matrix=bt709:out_range=tv,format=yuv420p'
        : 'scale=in_range=full:out_range=tv:out_color_matrix=bt709,format=yuv420p',
      '-c:v', 'libx264',
      '-preset', 'fast',
      '-crf', '18',
      '-pix_fmt', 'yuv420p',
      '-color_range', 'tv',
      '-colorspace', 'bt709',
      '-color_primaries', 'bt709',
      '-color_trc', 'bt709',
      ...(noAudio
        ? []
        : ['-c:a', 'aac', '-b:a', '192k', '-ar', '48000', '-ac', '2', '-af', 'loudnorm=I=-16:TP=-1.5:LRA=7']),
      '-movflags', '+faststart',
      '-shortest',
      outMp4
    );

    const ff = spawn('ffmpeg', ffArgs, { stdio: ['pipe', 'pipe', 'pipe'] });
    let ffErr = '';
    ff.stderr.on('data', (d) => { ffErr += d.toString('utf8'); });
    const ffExit = new Promise((resolve, reject) => {
      ff.once('error', reject);
      ff.once('close', (code) => resolve(code));
    });

    console.log(`[render.mjs] Rendering ${TOTAL_FRAMES} frames (${timings.totalDuration.toFixed(2)}s @ ${FPS}fps, ${WIDTH}x${HEIGHT}) -> ${outMp4}`);
    const tRender = Date.now();
    let nextLogFrame = 0;

    for (let f = 0; f < TOTAL_FRAMES; f += pageWorkers.length) {
      const batchCount = Math.min(pageWorkers.length, TOTAL_FRAMES - f);
      const buffers = await Promise.all(
        Array.from({ length: batchCount }, (_, j) => renderFrameOn(pageWorkers[j], f + j))
      );
      for (const buf of buffers) {
        if (!ff.stdin.write(buf)) {
          await once(ff.stdin, 'drain');
        }
      }
      const done = f + batchCount;
      if (done === TOTAL_FRAMES || done >= nextLogFrame) {
        const elapsed = (Date.now() - tRender) / 1000;
        const rateFps = done / Math.max(0.01, elapsed);
        console.log(`[render.mjs] Frame ${done}/${TOTAL_FRAMES} (${((done / TOTAL_FRAMES) * 100).toFixed(0)}%) | ${rateFps.toFixed(1)} fps | ${elapsed.toFixed(1)}s`);
        nextLogFrame = done + FPS * 5;
      }
    }

    ff.stdin.end();
    const code = await ffExit;
    if (code !== 0) {
      die(`FFmpeg exited with code ${code}:\n${ffErr}`);
    }

    // Release headless browser memory before running post-render verification & contact sheet
    for (const w of pageWorkers) { try { w.close(); } catch {} }
    pageWorkers.length = 0;
    try { browserCdp?.close(); } catch {}
    browserCdp = null;
    try { chromeProc?.kill('SIGKILL'); } catch {}
    chromeProc = null;

    // ---------- Post-render verification via ffprobe + full decode ----------
    const probeJson = JSON.parse(
      execFileSync(
        'ffprobe',
        [
          '-v', 'error',
          '-show_entries', 'format=duration,size,bit_rate:stream=codec_type,codec_name,width,height,r_frame_rate,pix_fmt,sample_rate,channels',
          '-of', 'json',
          outMp4
        ],
        { encoding: 'utf8' }
      )
    );

    const vStream = probeJson.streams.find((s) => s.codec_type === 'video');
    const aStream = probeJson.streams.find((s) => s.codec_type === 'audio');
    if (!vStream) die('Verification failed: missing video stream');
    if (vStream.width !== WIDTH || vStream.height !== HEIGHT) {
      die(`Verification failed: expected ${WIDTH}x${HEIGHT}, got ${vStream.width}x${vStream.height}`);
    }
    if (vStream.pix_fmt !== 'yuv420p') {
      die(`Verification failed: expected yuv420p, got ${vStream.pix_fmt}`);
    }
    if (!noAudio && !aStream) {
      die('Verification failed: missing audio stream');
    }

    execFileSync('ffmpeg', ['-v', 'error', '-threads', '2', '-i', outMp4, '-f', 'null', '-'], { stdio: ['ignore', 'pipe', 'pipe'] });

    const dur = parseFloat(probeJson.format.duration);
    const outBase = outMp4.replace(/\.mp4$/i, '');
    const contactPath = `${outBase}-contact.jpg`;
    const sampleRateFilter = (16 / Math.max(0.5, dur)).toFixed(6);
    execFileSync(
      'ffmpeg',
      [
        '-y', '-v', 'error',
        '-threads', '1',
        '-i', outMp4,
        '-vf', `fps=${sampleRateFilter},scale=640:-1,tile=4x4:padding=4:color=#0a0908`,
        '-frames:v', '1',
        '-update', '1',
        '-q:v', '3',
        contactPath
      ],
      { stdio: ['ignore', 'pipe', 'pipe'] }
    );

    const elapsedTotal = ((Date.now() - t0) / 1000).toFixed(1);
    const sizeMb = (Number(probeJson.format.size) / (1024 * 1024)).toFixed(2);
    console.log(`[render.mjs] VERIFIED OK in ${elapsedTotal}s: ${outMp4} (${sizeMb} MB, ${dur.toFixed(2)}s, ${vStream.width}x${vStream.height} ${vStream.r_frame_rate} ${vStream.pix_fmt}, audio=${aStream ? `${aStream.codec_name} ${aStream.sample_rate}Hz ${aStream.channels}ch` : 'none'})`);
    console.log(`[render.mjs] Contact sheet: ${contactPath}`);
  }
} finally {
  for (const w of pageWorkers) { try { w.close(); } catch {} }
  try { browserCdp?.close(); } catch {}
  try { chromeProc?.kill('SIGKILL'); } catch {}
  try { httpServer?.close(); } catch {}
  for (let i = 0; i < 4; i++) {
    try {
      fs.rmSync(userDataDir, { recursive: true, force: true });
      break;
    } catch {
      await new Promise((r) => setTimeout(r, 150));
    }
  }
}
